def make_id(category_id: str, title: str, index: int) -> str:
    slug = re.sub(r"[^a-z0-9]+", "_", category_id.lower()).strip("_")
    return f"{slug}_{index + 1:02d}"


def apply_text_card_title_corrections(gold_cards: list[dict]) -> int:
    changed = 0
    for gold in gold_cards:
        replacements = TEXT_CARD_TITLE_CORRECTIONS.get(gold.get("id"), {})
        if not replacements:
            continue
        for card in gold.get("cards", []):
            if card.get("imageKey"):
                continue
            old_title = card.get("title")
            new_title = replacements.get(old_title)
            if new_title and new_title != old_title:
                card["title"] = new_title
                changed += 1
    return changed


def main() -> int:
    payload = json.loads(CARDS_PATH.read_text(encoding="utf-8"))
    gold_cards = payload["goldCards"]
    by_id = {gold["id"]: gold for gold in gold_cards}

    for category_id, title, words in EXPANSION_CATEGORIES:
        cards = [
            {
                "id": make_id(category_id, word, index),
                "title": word,
                "imageKey": None,
                "difficulty": "rare" if index >= 8 else "normal",
                "tags": [category_id, "text_expansion"],
            }
            for index, word in enumerate(words)
        ]
        category_payload = {
            "id": category_id,
            "title": title,
            "contentType": "TextOnly",
            "cards": cards,
        }
        if category_id in by_id:
            by_id[category_id].update(category_payload)
        else:
            gold_cards.append(category_payload)

    corrected = apply_text_card_title_corrections(gold_cards)

    CARDS_PATH.write_text(
        json.dumps(payload, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )
    print(f"gold_categories={len(gold_cards)}")
    print(f"added_or_updated={len(EXPANSION_CATEGORIES)}")
    print(f"text_card_title_corrections={corrected}")
    print(f"cards_total={sum(len(gold['cards']) for gold in gold_cards)}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
